from django.conf import settings
from django.db import migrations, models


def attach_existing_schedule(apps, schema_editor):
    """Exam dates saved before sessions existed go into one session, so hall
    tickets keep working exactly as before. It is the current session until
    the exam cell sets up the next one."""
    ExamSchedule = apps.get_model("exams", "ExamSchedule")
    ExamSession = apps.get_model("exams", "ExamSession")
    rows = ExamSchedule.objects.filter(exam_session__isnull=True)
    if not rows.exists():
        return
    sems = sorted(set(rows.values_list("semester", flat=True)))
    first = rows.order_by("exam_date").first().exam_date
    last = rows.order_by("-exam_date").first().exam_date
    sess = ExamSession.objects.create(
        name="Earlier exams", exam_start=first, exam_end=last, semesters=sems,
        registration_required=False, registration_closed=True, fee_required=False,
        is_current=True, timetable_published=True, hall_tickets_released=True,
    )
    rows.update(exam_session=sess)

